// Schema mirrors prisma/schema.prisma; generated by scripts/prepare-d1.mjs.
import {
  sqliteTable,
  text,
  integer,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";
import { sql } from "drizzle-orm";

export const Category = sqliteTable("Category", {
  id: text("id").primaryKey(),
  title: text("title").notNull(),
  titleTr: text("titleTr").notNull(),
  description: text("description").notNull(),
  descriptionTr: text("descriptionTr").notNull(),
  image: text("image").notNull(),
});

export const Product = sqliteTable("Product", {
  id: text("id").primaryKey(),
  slug: text("slug").notNull().unique(),
  sku: text("sku").notNull().unique(),
  title: text("title").notNull(),
  titleTr: text("titleTr").notNull(),
  description: text("description").notNull(),
  descriptionTr: text("descriptionTr").notNull(),
  categoryId: text("categoryId")
    .notNull()
    .references(() => Category.id),
  subcategory: text("subcategory").notNull(),
  industry: text("industry").notNull(),
  saleMode: text("saleMode").notNull().default("STANDARD_ORDER"),
  visible: integer("visible", { mode: "boolean" }).notNull().default(true),
  baseCents: integer("baseCents").notNull(),
  moq: integer("moq").notNull().default(100),
  packMultiple: integer("packMultiple").notNull().default(50),
  specs: text("specs").notNull(),
  sourceUrl: text("sourceUrl").notNull(),
  updatedAt: text("updatedAt").notNull(),
});

export const ProductImage = sqliteTable("ProductImage", {
  id: text("id").primaryKey(),
  productId: text("productId")
    .notNull()
    .references(() => Product.id, { onDelete: "cascade" }),
  src: text("src").notNull(),
  alt: text("alt").notNull(),
  position: integer("position").notNull(),
});

export const ProductVariant = sqliteTable("ProductVariant", {
  id: text("id").primaryKey(),
  productId: text("productId")
    .notNull()
    .references(() => Product.id, { onDelete: "cascade" }),
  sku: text("sku").notNull().unique(),
  shape: text("shape").notNull(),
  size: text("size").notNull(),
  finish: text("finish").notNull(),
  color: text("color").notNull(),
  thickness: text("thickness").notNull(),
  pack: integer("pack").notNull().default(50),
  adjustmentCents: integer("adjustmentCents").notNull().default(0),
  demoCapacity: integer("demoCapacity").notNull().default(10000),
});

export const PricingTier = sqliteTable(
  "PricingTier",
  {
    id: text("id").primaryKey(),
    productId: text("productId")
      .notNull()
      .references(() => Product.id, { onDelete: "cascade" }),
    minQty: integer("minQty").notNull(),
    discountBps: integer("discountBps").notNull(),
  },
  (table) => [
    uniqueIndex("PricingTier_productId_minQty_key").on(
      table.productId,
      table.minQty,
    ),
  ],
);

export const Company = sqliteTable("Company", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  country: text("country").notNull(),
  address: text("address").notNull().default(""),
  phone: text("phone").notNull().default(""),
});

export const User = sqliteTable("User", {
  id: text("id").primaryKey(),
  email: text("email").notNull().unique(),
  name: text("name").notNull(),
  passwordHash: text("passwordHash").notNull(),
  role: text("role").notNull().default("PENDING_BUYER"),
  companyId: text("companyId").references(() => Company.id),
});

export const Session = sqliteTable("Session", {
  id: text("id").primaryKey(),
  userId: text("userId")
    .notNull()
    .references(() => User.id, { onDelete: "cascade" }),
  expiresAt: text("expiresAt").notNull(),
});

export const WholesaleApplication = sqliteTable("WholesaleApplication", {
  id: text("id").primaryKey(),
  userId: text("userId")
    .notNull()
    .references(() => User.id),
  company: text("company").notNull(),
  name: text("name").notNull(),
  email: text("email").notNull(),
  phone: text("phone").notNull(),
  country: text("country").notNull(),
  businessType: text("businessType").notNull(),
  monthlyVolume: text("monthlyVolume").notNull(),
  interests: text("interests").notNull(),
  notes: text("notes").notNull(),
  status: text("status").notNull().default("PENDING"),
  createdAt: text("createdAt")
    .notNull()
    .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
});

export const Order = sqliteTable("Order", {
  id: text("id").primaryKey(),
  userId: text("userId")
    .notNull()
    .references(() => User.id),
  company: text("company").notNull(),
  name: text("name").notNull(),
  email: text("email").notNull(),
  phone: text("phone").notNull(),
  country: text("country").notNull(),
  shippingAddress: text("shippingAddress").notNull(),
  billingAddress: text("billingAddress").notNull(),
  notes: text("notes").notNull(),
  status: text("status").notNull().default("RECORDED"),
  currency: text("currency").notNull().default("USD"),
  totalCents: integer("totalCents").notNull(),
  idempotencyKey: text("idempotencyKey").notNull().unique(),
  createdAt: text("createdAt")
    .notNull()
    .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
});

export const OrderItem = sqliteTable("OrderItem", {
  id: text("id").primaryKey(),
  orderId: text("orderId")
    .notNull()
    .references(() => Order.id, { onDelete: "cascade" }),
  productId: text("productId").notNull(),
  variantId: text("variantId").notNull(),
  title: text("title").notNull(),
  titleTr: text("titleTr").notNull(),
  variantLabel: text("variantLabel").notNull(),
  image: text("image").notNull(),
  quantity: integer("quantity").notNull(),
  unitCents: integer("unitCents").notNull(),
  totalCents: integer("totalCents").notNull(),
});

export const QuoteRequest = sqliteTable("QuoteRequest", {
  id: text("id").primaryKey(),
  userId: text("userId").references(() => User.id),
  family: text("family").notNull(),
  application: text("application").notNull(),
  shape: text("shape").notNull(),
  dimensions: text("dimensions").notNull(),
  thickness: text("thickness").notNull(),
  finish: text("finish").notNull(),
  quantity: integer("quantity").notNull(),
  country: text("country").notNull(),
  company: text("company").notNull(),
  name: text("name").notNull(),
  email: text("email").notNull(),
  phone: text("phone").notNull(),
  notes: text("notes").notNull(),
  status: text("status").notNull().default("NEW"),
  response: text("response").notNull().default(""),
  createdAt: text("createdAt")
    .notNull()
    .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
});

export const ContactSubmission = sqliteTable("ContactSubmission", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  company: text("company").notNull(),
  email: text("email").notNull(),
  message: text("message").notNull(),
  createdAt: text("createdAt")
    .notNull()
    .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
});

export const SeedState = sqliteTable("SeedState", {
  id: text("id").primaryKey(),
  appliedAt: text("appliedAt").notNull(),
});
